package local.pitv;
import android.app.*;import android.content.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

/** Home-owned, daily refresh; keeps successful metadata on disk, not whole videos. */
final class TrailerReel {
 final MainActivity app;final HashMap<String,JSONObject> entries=new HashMap<>();JSONArray pending;boolean refreshing;long retryAfter;final Handler handler=new Handler();final Runnable daily=()->refresh(false);
 TrailerReel(MainActivity a){app=a;}
 boolean enabled(){return app.getSharedPreferences("trailer-feed",0).getBoolean("enabled",false);}
 void load(){JSONArray saved=TheatricalTrailers.read(app,TheatricalTrailers.CACHE);if(saved.length()>0)apply(saved);else status(app.getSharedPreferences("trailer-feed",0).getLong(TheatricalTrailers.UPDATED,0)>0?"Trailer feed unavailable · select to retry":"Loading latest trailers…");refresh(false);}
 void apply(JSONArray data){String playing=app.promoReady&&!app.clips.isEmpty()?app.clips.get(app.clip%app.clips.size()):app.resumeUrl;entries.clear();ArrayList<String> available=new ArrayList<>();for(int i=0;i<data.length();i++){JSONObject item=data.optJSONObject(i);if(item==null)continue;String url=item.optString("url");if(url.isEmpty())continue;entries.put(url,item);available.add(url);}if(available.isEmpty()){app.promoReady=false;app.promo.stopPlayback();app.clips.clear();app.resumeUrl="";app.resumePosition=0;app.promoTitle.setVisibility(View.GONE);status("Trailer feed unavailable · select to retry");return;}app.clips=MainActivity.mergeReelOrder(available,app.getPreferences(0).getString("reelOrder","[]"));int at=app.clips.indexOf(playing);app.clip=Math.max(0,at);if(app.promoReady&&at>=0){label();return;}app.restoreClip();app.startClip();}
 void refresh(boolean force){handler.removeCallbacks(daily);if(!enabled()||!app.active||app.isDestroyed()||refreshing)return;long now=System.currentTimeMillis();if(!force&&(!TheatricalTrailers.due(app)||now<retryAfter)){schedule();return;}refreshing=true;app.worker.submit(()->{JSONArray result=null;try{result=TheatricalTrailers.refresh(app);}catch(Exception ignored){}final JSONArray found=result;app.runOnUiThread(()->{refreshing=false;if(app.isDestroyed()||!enabled())return;if(found==null){retryAfter=System.currentTimeMillis()+60*60*1000L;if(app.active&&app.clips.isEmpty())status("Trailer update unavailable · check Trailer setup in Settings");}else if(app.active){if(app.promoReady)pending=found;else apply(found);}if(app.active)schedule();});});}
 void schedule(){if(!enabled()||!app.active)return;long updated=app.getSharedPreferences("trailer-feed",0).getLong(TheatricalTrailers.UPDATED,0);long next=Math.max(updated+TheatricalTrailers.DAY,retryAfter);handler.postDelayed(daily,Math.max(60000,next-System.currentTimeMillis()));}
 void resume(){if(enabled()){if(app.clips.isEmpty())load();else refresh(false);}}
 void pause(){handler.removeCallbacks(daily);}
 void next(){if(pending!=null){JSONArray data=pending;pending=null;String next=app.clips.isEmpty()?"":app.clips.get(app.clip%app.clips.size());app.promoReady=false;app.resumeUrl=next;app.resumePosition=0;apply(data);}else app.startClip();}
 int duration(String url){JSONObject item=entries.get(url);return item==null?0:item.optInt("durationMs");}
 void label(){if(app.promoTitle==null)return;if(!enabled()||app.clips.isEmpty()){app.promoTitle.setVisibility(View.GONE);return;}JSONObject item=entries.get(app.clips.get(app.clip%app.clips.size()));if(item==null)return;app.promoTitle.setText(item.optString("title"));app.promoTitle.setVisibility(View.VISIBLE);}
 void status(String text){app.promoStatus.setText(text);app.promoStatus.setVisibility(View.VISIBLE);}
 void settings(){CheckBox on=new CheckBox(app);on.setText("Play latest trailers · unfiltered");on.setPadding(app.dp(20),app.dp(12),app.dp(20),app.dp(12));on.setChecked(enabled());new AlertDialog.Builder(app).setTitle("Trailer feed").setMessage("Moviefone's complete latest feed: movies in theaters, upcoming movies, streaming releases, and TV trailers. Refreshes daily. No TMDB key is needed.").setView(on).setPositiveButton("Save",(d,w)->{app.getSharedPreferences("trailer-feed",0).edit().putBoolean("enabled",on.isChecked()).apply();app.home();}).setNegativeButton("Cancel",(d,w)->app.resumeReel()).setOnCancelListener(d->app.resumeReel()).show();}
}
